package za.ac.cput.repository; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import za.ac.cput.domain.Notification; import static org.junit.jupiter.api.Assertions.*; @SpringBootTest class NotificationRepositoryImplTest{@Autowired NotificationRepository repository; @Test void saveReadDelete(){Notification x=za.ac.cput.factory.NotificationFactory.createNotification("N001","C1","B1","Hello",java.time.LocalDateTime.now(),"Email"); repository.save(x); assertTrue(repository.findById("N001").isPresent()); repository.deleteById("N001"); assertTrue(repository.findById("N001").isEmpty());}}